    exercice: { titre: "Formulaire et e-mail de confirmation", consigne: "Reliez un formulaire à un e-mail de confirmation automatique, authentifiez votre domaine d'envoi et testez.", champs: [{ label: "Le chemin : formulaire → outil → e-mail" }, { label: "Enregistrements d'authentification ajoutés (SPF, DKIM, DMARC) selon le service" }, { label: "Résultat sur 3 messageries (boîte principale ou indésirables)" }, { label: "Le consentement recueilli, si une liste est alimentée" }] },
    prompt: { titre: "Relire un e-mail", texte: "Voici mon e-mail de confirmation : [TEXTE].\nIdentifie ce qui pourrait le faire classer en indésirable (objet, mots, liens, mise en forme) et ce qui relève du marketing dans un e-mail qui devrait être purement transactionnel.\nPropose une version plus sobre. Rappelle-moi de vérifier les règles de mon pays sur le consentement.", conseil: "Testez l'e-mail final sur plusieurs messageries." },
